export const getGetIndustryRankingsUrl = (industryId: number,
    params: GetIndustryRankingsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/industries/${industryId}/rankings?${stringifiedParams}` : `/api/industries/${industryId}/rankings`
}

